import{_ as t,o,c as s,a2 as n}from"./chunks/framework.CXsxtpvq.js";const r="/asset-studio/shots/en/03-jobs-setup-full.webp",a="/asset-studio/shots/en/04-jobs-preview.webp",i="/asset-studio/shots/en/06-queue.webp",f=JSON.parse('{"title":"Generating images","description":"","frontmatter":{},"headers":[],"relativePath":"guide/generate.md","filePath":"guide/generate.md"}'),d={name:"guide/generate.md"};function l(h,e,g,c,u,p){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="generating-images" tabindex="-1">Generating images <a class="header-anchor" href="#generating-images" aria-label="Permalink to &quot;Generating images&quot;">​</a></h1><p>The <strong>Jobs</strong> menu queues characters × outfits × expressions × count in one go.</p><p><img src="'+r+'" alt="The Jobs screen"></p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li>Choose the <strong>Work</strong> and tick <strong>characters</strong> on the left. You can pick several.</li><li>Tick <strong>Outfit set</strong>. The outfits the chosen characters can use are listed.</li><li>Check <strong>Slots to include</strong>. Choosing an expression ticks the slots its composition suggests.</li><li>Tick <strong>Expression</strong>. <strong>Select all in this category</strong> picks them all at once.</li><li>Under <strong>Composition · style · common</strong>, tick what you need. Without a composition, each expression uses its own.</li><li>Choose the model and sampler under <strong>Generation settings</strong> and set <strong>Images per combination</strong>.</li><li>Check the count in the bar at the bottom (characters × outfits × expressions × count) and press <strong>Queue N</strong>.</li></ol><h2 id="generation-settings" tabindex="-1">Generation settings <a class="header-anchor" href="#generation-settings" aria-label="Permalink to &quot;Generation settings&quot;">​</a></h2><p>The <strong>Anima</strong> / <strong>SDXL·IL</strong> tabs choose the model family. Switching shows only models and pieces of that family.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Notes</th></tr></thead><tbody><tr><td>Model</td><td>A diffusion model or checkpoint. <code>[checkpoint]</code> marks fine-tunes with their own text encoder.</td></tr><tr><td>Text encoder · VAE · CLIP type</td><td>Needed for Anima. For a checkpoint-style fine-tune, pick its own text encoder.</td></tr><tr><td>Sampler · scheduler · steps · CFG</td><td>As in ComfyUI.</td></tr><tr><td>Width · height</td><td>For images you will train a LoRA on, square (for example 1536×1536) is recommended.</td></tr><tr><td>Seed</td><td>-1 is random. <strong>One fixed seed per character</strong> uses one seed per character for all of that queueing.</td></tr><tr><td>LoRA</td><td>LoRAs you add yourself. Trained and registered LoRAs are added automatically while <strong>Apply registered LoRAs automatically</strong> is on.</td></tr></tbody></table><p>Save settings you use often with <strong>Save new preset</strong> and load them from <strong>Settings preset</strong>. To also keep the expression choice, composition and style, use <strong>Combination presets</strong> at the top.</p><h2 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h2><p><strong>Preview</strong> under <strong>Preview of the first combination</strong> shows the real prompt of the first combination. Check that the pieces joined the way you meant before queueing. LoRAs that will be applied automatically are listed as &quot;Automatic LoRAs&quot;.</p><p><img src="'+a+'" alt="Combination preview"></p><ul><li><strong>Download workflow</strong>: save this combination as a ComfyUI workflow file.</li><li><strong>Generate once with these settings</strong> / <strong>Open in Lab</strong>: hand it to the lab to make a single image or try other settings.</li><li><strong>Edit the prompt for this run only</strong>: change the prompt for this queueing without touching the library.</li></ul><h2 id="the-queue" tabindex="-1">The queue <a class="header-anchor" href="#the-queue" aria-label="Permalink to &quot;The queue&quot;">​</a></h2><p>The queue button at the top shows running and queued jobs; press it to open the queue panel.</p><p><img src="'+i+'" alt="The queue panel"></p><ul><li><strong>Pause after the current job</strong>: finishes the image being made, then stops.</li><li><strong>Cancel queued jobs</strong>: cancels everything that has not started.</li><li>A failed job pauses the queue. Read the error, fix the cause and resume.</li></ul><p>Images are saved under <code>outputs/&lt;work&gt;/&lt;character&gt;/&lt;outfit&gt;/</code> as <code>&lt;expression code&gt;.png</code>; making the same expression again adds <code>_002</code>, <code>_003</code> and so on.</p>',18)])])}const b=t(d,[["render",l]]);export{f as __pageData,b as default};
